<template><div class="overflow-x-auto"><table class="min-w-[720px] w-full text-left text-sm"><thead><tr class="border-b border-gray-200 text-xs uppercase text-gray-500 dark:border-dark-700"><th class="px-4 py-3">Model</th><th class="px-4 py-3">Domain</th><th class="px-4 py-3">Health</th><th class="px-4 py-3">Delta</th><th class="px-4 py-3">CI</th><th class="px-4 py-3">Samples</th><th class="px-4 py-3">P99</th></tr></thead><tbody><tr v-for="row in rows" :key="row.model_route + row.capability_domain" class="border-b border-gray-100 dark:border-dark-800"><td class="px-4 py-3 font-medium dark:text-white">{{ row.model_route }}</td><td class="px-4 py-3">{{ row.capability_domain ?? 'aggregate' }}</td><td class="px-4 py-3"><Status :value="row.health_state ?? 'insufficient_evidence'" /></td><td class="px-4 py-3">{{ row.delta_pp == null ? 'n/a' : `${row.delta_pp.toFixed(2)} pp` }}</td><td class="px-4 py-3">{{ row.ci_low_pp == null ? 'n/a' : `${row.ci_low_pp.toFixed(2)} / ${(row.ci_high_pp ?? 0).toFixed(2)}` }}</td><td class="px-4 py-3">{{ row.sample_count ?? 'n/a' }}</td><td class="px-4 py-3">{{ row.p99_ms == null ? 'n/a' : `${row.p99_ms} ms` }}</td></tr></tbody></table><div v-if="!rows.length" class="p-5 text-sm text-gray-500">No model observations available</div></div></template><script setup lang="ts">import type { RadarModelHealth } from '@/api/admin/radar'; import Status from './Status.vue'; defineProps<{ rows: RadarModelHealth[] }>();</script>
